use crate::aap::caps::state_read;

const SUBSCRIPTIONS_KEY: &str = "urls";

/// Stored value format: one URL per line. Blank lines and surrounding
/// whitespace are ignored.
fn parse_urls(text: &str) -> Vec<String> {
    text.lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(String::from)
        .collect()
}

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let urls = match state_read::get(SUBSCRIPTIONS_KEY) {
            Some(text) => parse_urls(&text),
            None => Vec::new(),
        };

        // `ensures present(urls)`: an output with no URLs would violate the
        // contract, and the return type has no way to signal absence. Trapping
        // here produces no output rather than a non-conforming one.
        if urls.is_empty() {
            panic!("LoadSubscriptions: no subscription URLs present in state");
        }

        SubscriptionList { urls }
    }
}

export!(Node);
```

I did not add the enrichment fetch. The `with` clause grants only `aap:caps/state-read@0.1.0`, so this node has no outbound HTTP capability, and adding one would exceed its authority. The input also has no text field: `RunInfo` carries only `date` and `started`. Sending request data to an external host would also change what leaves the node, which the spec rules out. If the enrichment is needed, it belongs in a node whose `with` clause grants `http-client` for that host.

